select is((select fulfillment_method from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000001'::uuid)),'legacy'::text,'pedido histórico no presume retiro');
select throws_ok($q$select public.create_evalia_order_delivery('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71110000-0000-4000-8000-000000000004'::uuid,'shipping',null)$q$,'22023','Tipo de entrega o destino no válidos','nuevo pedido sin destino rechazado');
select lives_ok($q$select public.create_evalia_order_delivery('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71110000-0000-4000-8000-000000000002'::uuid,'shipping','La Paz - Terminal')$q$,'nuevo pedido con destino y snapshot');
select is((select fulfillment_method from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'shipping'::text,'modalidad envío persistida');
select is((select shipping_destination from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'La Paz - Terminal'::text,'destino persistido');
select is((select recipient_name from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'Nombre antiguo'::text,'destinatario congelado');
select is((select recipient_phone from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'70011122'::text,'número congelado');
select lives_ok($q$select public.create_evalia_order_delivery('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71110000-0000-4000-8000-000000000002'::uuid,'shipping','La Paz - Terminal')$q$,'reintento de envío idempotente');
select is((select count(*)::integer from public.order_fulfillment_revisions where order_id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),1::integer,'una sola ficha de entrega');
select throws_ok($q$select public.create_evalia_order_delivery('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71110000-0000-4000-8000-000000000002'::uuid,'shipping','Tarija')$q$,'23505','Pedido repetido con entrega diferente','reintento de distinto destino rechazado');
select lives_ok($q$select public.update_evalia_customer_delivery('30000000-0000-4000-8000-000000000001'::uuid,'Nombre nuevo','78900123','shipping','Sucre / Agencia',
 (select updated_at from public.customers where id='30000000-0000-4000-8000-000000000001'::uuid),'81110000-0000-4000-8000-000000000001'::uuid)$q$,'cliente actualizado con destino habitual');
select is((select shipping_destination from public.customers where id='30000000-0000-4000-8000-000000000001'::uuid),'Sucre / Agencia'::text,'cliente de envío tiene destino');
select is((select recipient_name from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'Nombre antiguo'::text,'cambio de cliente no cambia nombre del pedido');
select is((select shipping_destination from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'La Paz - Terminal'::text,'cambio de cliente no cambia destino del pedido');
select is((select recipient_phone from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'70011122'::text,'cambio de cliente no cambia número del pedido');
select lives_ok($q$select public.update_evalia_order_delivery((select id from public.orders where request_id='71110000-0000-4000-8000-000000000001'::uuid),'pickup',null,'81110000-0000-4000-8000-000000000003'::uuid)$q$,'clasificar pedido antiguo para retiro');
select is((select fulfillment_method from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000001'::uuid)),'pickup'::text,'pedido antiguo clasificado explícitamente');
select lives_ok($q$select public.update_evalia_order_delivery((select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid),'shipping','Tarija / Terminal','81110000-0000-4000-8000-000000000002'::uuid)$q$,'cambiar destino solo en el pedido activo');
select is((select shipping_destination from public.orders where id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),'Tarija / Terminal'::text,'destino corregido en pedido');
select is((select shipping_destination from public.customers where id='30000000-0000-4000-8000-000000000001'::uuid),'Sucre / Agencia'::text,'cambio de pedido no afecta destino habitual');
select lives_ok($q$select public.update_evalia_order_delivery((select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid),'shipping','Tarija / Terminal','81110000-0000-4000-8000-000000000002'::uuid)$q$,'reintento cambio de destino idempotente');
select is((select count(*)::integer from public.order_fulfillment_revisions where order_id=(select id from public.orders where request_id='71110000-0000-4000-8000-000000000002'::uuid)),2::integer,'solo 2 eventos entrega: creación y corrección');
select throws_ok($q$select public.update_evalia_customer_delivery('30000000-0000-4000-8000-000000000001'::uuid,'Otro','123','shipping','',now(),'81110000-0000-4000-8000-000000000009'::uuid)$q$,'22023','Categoría y destino del cliente no válidos','categoría envío sin destino siempre rechazada');
set local request.jwt.claim.sub = '10000000-0000-4000-8000-000000000099';
select throws_ok($q$select public.create_evalia_order_delivery('30000000-0000-4000-8000-000000000001'::uuid,'[{"modelId":"20000000-0000-4000-8000-000000000001","dozens":1,"extraColorIds":[]}]'::jsonb,'71110000-0000-4000-8000-000000000009'::uuid,'pickup',null)$q$,'42501','Acceso administrativo requerido','usuario no-admin no registra entrega');
reset role;
select ok((not has_function_privilege('anon','public.create_evalia_order_delivery(uuid,jsonb,uuid,text,text)','EXECUTE')),'anónimo no ejecuta pedido');
select ok((not has_function_privilege('service_role','public.create_evalia_order_delivery(uuid,jsonb,uuid,text,text)','EXECUTE')),'service_role no crea pedidos sin usuario');
select ok((not has_table_privilege('authenticated','public.order_fulfillment_revisions','INSERT')),'auditoría de modalidad inmutable');
select ok((not has_column_privilege('authenticated','public.customers','shipping_destination','UPDATE')),'destino cliente no editable directo');
select ok((not has_column_privilege('authenticated','public.orders','shipping_destination','UPDATE')),'destino pedido no editable directo');
select * from finish();
rollback;
